"""Pairwise evolutionary distance measures for aligned sequences."""

import math


def _validate(a: str, b: str) -> float:
    """Check alignment and return the p-distance (proportion of mismatches)."""
    if len(a) != len(b):
        raise ValueError("sequences must be aligned (equal length)")
    if not a:
        raise ValueError("sequences must be non-empty")
    differences = sum(1 for x, y in zip(a, b) if x != y)
    return differences / len(a)


def p_distance(a: str, b: str) -> float:
    """Proportion of differing sites between two aligned, equal-length sequences."""
    return _validate(a, b)


def jukes_cantor(a: str, b: str) -> float:
    """Jukes-Cantor corrected distance: -3/4 * ln(1 - 4p/3).

    Raises ValueError when p >= 0.75 (log of a non-positive number).
    """
    p = _validate(a, b)
    if p >= 0.75:
        raise ValueError(
            f"p-distance {p} >= 0.75: Jukes-Cantor correction undefined"
        )
    return -0.75 * math.log(1.0 - 4.0 * p / 3.0)

