"""UPGMA (unweighted pair group method with arithmetic mean) clustering."""

from typing import Dict, Sequence, Tuple, Union

# A leaf is a label string; an internal node is (height, left, right).
Node = Union[str, tuple]


def build_upgma_tree(
    labels: Sequence[str], matrix: Dict[Tuple[str, str], float]
) -> Node:
    """Build a UPGMA tree from a pairwise distance matrix.

    labels: sequence of taxon names.
    matrix: dict mapping (label_i, label_j) to the distance; both key
        orderings are accepted.

    Returns the root node. Leaves are label strings; internal nodes are
    tuples (height, left_child, right_child), where height is the UPGMA
    merge distance.
    """
    clusters = {label: label for label in labels}
    # Cluster-to-cluster distances, keyed by frozenset of cluster names.
    dists: Dict[frozenset, float] = {}
    for (i, j), d in matrix.items():
        dists[frozenset((i, j))] = d

    def cluster_distance(c1: set, c2: set) -> float:
        """Average distance between all cross pairs of two clusters."""
        total = 0.0
        n = 0
        for i in c1:
            for j in c2:
                total += dists[frozenset((i, j))]
                n += 1
        return total / n

    while len(clusters) > 1:
        names = list(clusters)
        # Find closest pair of clusters.
        best = None
        best_d = None
        for a in range(len(names)):
            for b in range(a + 1, len(names)):
                d = cluster_distance(set(_leaves(clusters[names[a]])),
                                     set(_leaves(clusters[names[b]])))
                if best_d is None or d < best_d:
                    best_d = d
                    best = (names[a], names[b])
        name_a, name_b = best
        merged_leaves = frozenset(
            _leaves(clusters[name_a]) | _leaves(clusters[name_b])
        )
        new_node = (best_d, clusters[name_a], clusters[name_b])

        # Replace the two old clusters with the merged one.
        del clusters[name_a], clusters[name_b]
        dists = {k: v for k, v in dists.items() if not k <= merged_leaves}
        for existing in clusters:
            existing_leaves = frozenset(_leaves(clusters[existing]))
            avg = (
                sum(dists[frozenset((e, m))]
                    for e in existing_leaves
                    for m in merged_leaves)
                / (len(existing_leaves) * len(merged_leaves))
            )
            dists[existing_leaves | merged_leaves] = avg
        clusters["|".join(sorted(merged_leaves))] = new_node
        # Keep leaves reachable from cluster names for later merges.
        _leaf_cache[id(new_node)] = set(merged_leaves)

    return next(iter(clusters.values()))


_leaf_cache: Dict[int, set] = {}


def _leaves(node: Node) -> set:
    """Set of taxon labels under a node."""
    if isinstance(node, str):
        return {node}
    cached = _leaf_cache.get(id(node))
    if cached is not None:
        return cached
    _, left, right = node
    return _leaves(left) | _leaves(right)


def to_newick(node: Node) -> str:
    """Render a tree as a Newick string (branch lengths are heights)."""
    if isinstance(node, str):
        return f"{node}"
    height, left, right = node
    return f"({to_newick(left)}:{height / 2:.6f},{to_newick(right)}:{height / 2:.6f})"

